package com.example.lms.controller;
import com.example.lms.dto.*; import com.example.lms.service.LibrarianService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.net.URI;
@RestController @RequestMapping("/api/librarians") public class LibrarianController {private final LibrarianService service; public LibrarianController(LibrarianService s){service=s;} @GetMapping public org.springframework.data.domain.Page<LibrarianResponse> list(@RequestParam(defaultValue="0") int page, @RequestParam(defaultValue="10") int size){return service.list(org.springframework.data.domain.PageRequest.of(page, size));} @GetMapping("/{id}") public LibrarianResponse get(@PathVariable Long id){return service.get(id);} @PostMapping public ResponseEntity<LibrarianResponse> create(@Valid @RequestBody LibrarianRequest r){var p=service.create(r);return ResponseEntity.created(URI.create("/api/librarians/"+p.id())).body(p);}@PutMapping("/{id}") public LibrarianResponse update(@PathVariable Long id,@Valid @RequestBody LibrarianUpdateRequest r){return service.update(id,r);}@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long id){service.delete(id);}}
